"""Install the final chronology accuracy correction without discarding a game."""
import json,pathlib
R=pathlib.Path(__file__).resolve().parents[1]
def patch(name,old,new):
 p=R/name;s=p.read_text()
 if new in s:return
 assert s.count(old)==1,(name,'Source anchor is absent or ambiguous; no speculative replacement')
 p.write_text(s.replace(old,new,1))
def main():
 dates=json.loads((R/'data/survival-chronology.json').read_text());report=json.loads((R/'data/survival-chronology-report.json').read_text())
 assert len(report['checks'])==report['reviewed']
 for ident,expected in [('steam:516750','2016-10-24'),('steam:387990','2016-01-19')]:
  assert dates['overrides'][ident]['earlyAccessReleaseDate']==expected,(ident,'Known official separate dates must be resolved')
 patch('scripts/survival_model.py',"'survival-media.json','survival-verified-stores.json'","'survival-media.json','survival-chronology.json','survival-verified-stores.json'")
 patch('scripts/survival_model.py',"  g['tags']=sorted(set(g.get('tags',[])+extra.get('tags',[])))","  g['tags']=sorted(set(g.get('tags',[])+extra.get('tags',[]))-{'Recent survival release'})")
 patch('scripts/survival_model.py',"old['tags']=sorted(set(old.get('tags',[])+g['tags']))","old['tags']=sorted((set(old.get('tags',[]))-{'Recent survival release'})|set(g['tags']))")
 patch('scripts/survival_model.py',"   old['storefronts']=normalized_links(old.get('storefronts',[])+g['storefronts'])","   for field in ['earlyAccessReleaseDate','releaseChronology']:\n    if g.get(field):old[field]=copy.deepcopy(g[field])\n   if g.get('originalReleaseYear'):old['originalReleaseYear']=min(old.get('originalReleaseYear') or g['originalReleaseYear'],g['originalReleaseYear'])\n   old['storefronts']=normalized_links(old.get('storefronts',[])+g['storefronts'])")
 patch('scripts/survival_model.py',"dates=[x.get('generatedAt') for x in [steam,external] if x.get('generatedAt')]","dates=[x.get('generatedAt') for x in [steam,external,load(root,'survival-chronology.json',{})] if x.get('generatedAt')]")
 patch('site/survival.js',"Recent first releases; old editions stay labelled.","Recent releases; earlier access dates stay visible.")
 patch('site/survival.js',"${g.originalReleaseYear?`<p>Original release:","${g.earlyAccessReleaseDate?`<p class=\"release-chronology\"><strong>Steam Early Access:</strong> ${esc(g.earlyAccessReleaseDate)}<br><strong>Store/full-release milestone:</strong> ${esc(g.releaseDate||g.releaseLabel)}. These are separate dates, not two games.</p>`:''}${g.originalReleaseYear?`<p>Original release:")
 patch('scripts/survival_wiki.py',"2025-2026 first releases, not old games made new by a patch.","2025-2026 store releases with confirmed earlier access excluded. Original non-Steam dates may be earlier; inspect each game's chronology.")
 patch('scripts/survival_wiki.py',"   if g.get('survivalWhy'):text+=", "   if g.get('earlyAccessReleaseDate'):text+='**Steam Early Access:** '+m(g['earlyAccessReleaseDate'])+'; **store/full-release milestone:** '+m(g.get('releaseDate') or g.get('releaseLabel'))+'. These are separate dates, not separate games.\\n\\n'\n   if g.get('survivalWhy'):text+=")
 patch('scripts/survival_wiki.py',"Old originals and new editions are dated separately where verified.","Old originals and new editions are dated separately where verified. Steam's separately labelled Early Access launch is shown alongside a later 1.0/store milestone. Confirmed pre-2025 access is excluded from the recent-discoveries shortcut; a missing history label is not proof of no earlier non-Steam release.")
 patch('scripts/survival_qa.py',"   assert page.locator('.survival-facts>div').count()==6", "   assert page.locator('.survival-facts>div').count()==6\n   if g.get('earlyAccessReleaseDate'):\n    chronology=page.locator('.release-chronology').inner_text();assert g['earlyAccessReleaseDate'] in chronology and (g.get('releaseDate') or g['releaseLabel']) in chronology,(g['name'],'release chronology not shown')")
 test=R/'tests/test_survival_chronology.py'
 content='''import json,pathlib,unittest\nR=pathlib.Path(__file__).resolve().parents[1]\nclass SurvivalChronologyTests(unittest.TestCase):\n @classmethod\n def setUpClass(cls):\n  cls.catalog=json.loads((R/'data/catalog.json').read_text());cls.by={g['id']:g for g in cls.catalog['items']};cls.dates=json.loads((R/'data/survival-chronology.json').read_text())['overrides'];cls.report=json.loads((R/'data/survival-chronology-report.json').read_text())\n def test_known_old_games_do_not_become_new_by_leaving_early_access(self):\n  for ident,early,milestone in [('steam:516750','2016-10-24','2025-01-08'),('steam:387990','2016-01-19','2026-07-24')]:\n   g=self.by[ident];self.assertEqual(g['earlyAccessReleaseDate'],early);self.assertEqual(g['releaseDate'],milestone);self.assertEqual(g['originalReleaseYear'],2016);self.assertNotIn('Recent survival release',g['tags'])\n def test_every_confirmed_date_survives_the_overlay(self):\n  self.assertGreaterEqual(len(self.dates),2)\n  for ident,d in self.dates.items():\n   g=self.by[ident];self.assertEqual(g['earlyAccessReleaseDate'],d['earlyAccessReleaseDate']);self.assertLessEqual(g['originalReleaseYear'],int(d['earlyAccessReleaseDate'][:4]));self.assertTrue(g['releaseChronology']['sourceUrl'].startswith('https://store.steampowered.com/app/'))\n   if g['originalReleaseYear']<2025:self.assertNotIn('Recent survival release',g['tags'])\n def test_review_coverage_is_reconciled_not_silently_truncated(self):\n  self.assertEqual(len(self.report['checks']),self.report['reviewed']);self.assertEqual(len({r['id'] for r in self.report['checks']}),self.report['reviewed']);self.assertEqual(len(self.dates),self.report['confirmedEarlierAccess']);self.assertEqual(sum(r['state']=='unresolved-active' for r in self.report['checks']),len(self.report['unresolved']))\n def test_complete_user_collection_and_media_stay_present(self):\n  rows=[g for g in self.catalog['items'] if any(h in g['hubs'] for h in ['Survival','Minecraft-like worlds'])];self.assertGreaterEqual(len(rows),381);self.assertGreaterEqual(len(self.by),1567);self.assertTrue(all(g.get('image') and g.get('trailers') and g.get('storefronts') for g in rows))\nif __name__=='__main__':unittest.main()\n'''
 if test.exists():assert test.read_text()==content
 else:test.write_text(content)
 print(json.dumps({'reviewed':report['reviewed'],'confirmedEarlierAccess':report['confirmedEarlierAccess'],'unresolvedSourceReads':len(report['unresolved']),'preserved':'All 381 study entries, exact store milestones, source links, complete media and prior hubs.'},indent=2))
if __name__=='__main__':main()
